  // from the split. Remove it to avoid an extra empty record.
  if (normalized.endsWith('\n') && rawRecords.length > 0 && rawRecords[rawRecords.length - 1] === '') {
    rawRecords.pop();
  }

  const records = [];
  for (const rawRecord of rawRecords) {
    records.push(parseRecord(rawRecord));
  }

  return records;
}

