  const fields = [];
  let currentField = '';
  let inQuotes = false;
  let i = 0;

  while (i < rawRecord.length) {
    const char = rawRecord[i];

    if (char === '"') {
      // Check for escaped quote ""
      if (inQuotes && i + 1 < rawRecord.length && rawRecord[i + 1] === '"') {
        currentField += '"';
        i += 2;
        continue;
      } else {
        inQuotes = !inQuotes;
        i++;
        continue;
      }
    }

    if (char === ',' && !inQuotes) {
      fields.push(currentField);
      currentField = '';
      i++;
      continue;
    }

    currentField += char;
    i++;
  }

  // End of record: check for unclosed quotes
  if (inQuotes) {
    throw new SyntaxError('Unclosed quoted field');
  }

  fields.push(currentField);

  return fields;
}
